import sys
import math

def gcd(a, b):
    while b:
        a, b = b, a % b
    return a

def solve():
    input_data = sys.stdin.read().split()
    if not input_data:
        return

    iterator = iter(input_data)
    try:
        T = int(next(iterator))
    except StopIteration:
        return

    results = []

    for _ in range(T):
        try:
            N = int(next(iterator))
        except StopIteration:
            break

        if N == 3:
            results.append("2 3 6")
            continue

        A = []
        for i in range(1, N + 1):
            val = i * (N + 1)
            A.append(str(val))

        results.append(" ".join(A))

    print("\n".join(results))

if __name__ == "__main__":
    solve()
